    /**
     * Astrada: logs requests and responses at the given level through OkHttp's
     * HttpLoggingInterceptor ({@code NONE} turns logging off). The {@code Authorization} header
     * (the bearer token) is always written as {@code ██}. {@code BODY} also logs request and
     * response bodies, which can hold cardholder data: use it in the sandbox only.
     *
     * @param level How much to log
     * @return ApiClient
     */
    public ApiClient setDebugging(Level level) {
        boolean debugging = level != null && level != Level.NONE;
        if (debugging && this.debugging) {
            loggingInterceptor.setLevel(level);
        } else if (debugging != this.debugging) {
            if (debugging) {
                loggingInterceptor = new HttpLoggingInterceptor();
                loggingInterceptor.redactHeader("Authorization");
                loggingInterceptor.setLevel(level);
                // Before co.astrada.client.http.SendOnce (the innermost interceptor of a builder client): after
                // it a POST or PATCH body is one-shot, which HttpLoggingInterceptor does not log.
                final OkHttpClient.Builder builder = httpClient.newBuilder();
                int at = builder.interceptors().size();
                for (int i = 0; i < builder.interceptors().size(); i++) {
                    if (builder.interceptors().get(i) instanceof co.astrada.client.http.SendOnce) {
                        at = i;
                        break;
                    }
                }
                builder.interceptors().add(at, loggingInterceptor);
                httpClient = builder.build();
            } else {
                final OkHttpClient.Builder builder = httpClient.newBuilder();
                builder.interceptors().remove(loggingInterceptor);
                httpClient = builder.build();
                loggingInterceptor = null;
            }
        }
        this.debugging = debugging;
        return this;
    }

